// Copy the game data the proposals draw from into lib/game.js — READ-ONLY on frontend/.
//   node --experimental-strip-types --no-warnings docs/item-proposals/tools/snapshot-game.mjs
// Nothing here is transcribed by hand: every stack, action, damage type, surface and rarity on the
// proposals page is this file's output, dated, so "what the game has" is never a guess.
import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
const D = new URL('../../../frontend/src/data/', import.meta.url).href;
const imp = p => import(D + p);
const { STACKS, POTIONS, THROWABLES, REAGENTS } = await imp('consumables/index.ts');
const { CLASSES } = await imp('classes/index.ts');
const { DAMAGE_TYPES } = await imp('damageTypes.ts').then(m => ({ DAMAGE_TYPES: m.DAMAGE_TYPES ?? Object.values(m).find(Array.isArray) }));
const { SURFACES, SURFACE_MATRIX } = await imp('surfaces.ts');
const { RARITIES } = await imp('items/rarity.ts');
const bases = await imp('items/bases/index.ts');
const BASES = bases.BASE_ITEMS ?? bases.BASES ?? Object.values(bases).find(v => Array.isArray(v) && v.length > 40);
const plain = v => JSON.parse(JSON.stringify(v));
const actions = CLASSES.flatMap(c => c.actions.map(a => ({ ...plain(a), cls: c.id })));
const game = {
  takenAt: new Date().toISOString(),
  stacks: plain(STACKS),
  potions: plain(POTIONS),
  throwables: plain(THROWABLES),
  reagents: plain(REAGENTS),
  actions,
  damageTypes: plain(DAMAGE_TYPES),
  surfaces: plain(SURFACES),
  surfaceMatrix: plain(SURFACE_MATRIX),
  rarities: plain(RARITIES),
  bases: plain(BASES).map(b => ({ id: b.id, name: b.name, slot: b.slot, silhouette: b.silhouette, damageType: b.damageType, tags: b.tags })),
};
const out = fileURLToPath(new URL('../lib/game.js', import.meta.url));
await writeFile(out, `// GENERATED by tools/snapshot-game.mjs from frontend/src/data — do not edit by hand.\nexport const GAME = ${JSON.stringify(game, null, 0)};\n`);
const kinds = {}; for (const s of game.stacks) kinds[s.kind] = (kinds[s.kind] ?? 0) + 1;
console.log('stacks', game.stacks.length, kinds, '· actions', actions.length, '· damage types', game.damageTypes.length, '· surfaces', game.surfaces.length, '· bases', game.bases.length);
